class Solution:
    def nextGreaterElements(self, nums: list[int]) -> list[int]:
        n = len(nums)
        ans = [-1] * n
        for i in range(n):
            for step in range(1, n):
                j = (i + step) % n
                if nums[j] > nums[i]:
                    ans[i] = nums[j]
                    break
        return ans

