class Solution:
    def nextGreaterElements(self, nums: list[int]) -> list[int]:
        n = len(nums)
        ans = [-1] * n
        stack = []
        for i in range(2 * n):
            idx = i % n
            while stack and nums[idx] > nums[stack[-1]]:
                ans[stack.pop()] = nums[idx]
            # Push each original index once to avoid duplicate work.
            if i < n:
                stack.append(idx)
        return ans

