class Solution:
    def nextGreaterElements(self, nums: list[int]) -> list[int]:
        n = len(nums)
        ans = [-1] * n
        stack = []
        for i in range(2 * n - 1, -1, -1):
            x = nums[i % n]
            while stack and stack[-1] <= x:
                stack.pop()
            if i < n and stack:
                ans[i] = stack[-1]
            stack.append(x)
        return ans

